        steps.push(step("\u0421\u0440\u0430\u0432\u043D\u0435\u043D\u0438\u0435 \u0441 \u0444\u0430\u043A\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u043C PaCO\u2082", `\u0444\u0430\u043A\u0442 PaCO\u2082 = ${fmt(paco2, 1)} \u043C\u043C \u0440\u0442. \u0441\u0442.; \u043E\u0436\u0438\u0434\u0430\u0435\u043C\u043E ${expectedPaCO2}`, compensation));
